head.b:skin:
:root{--z:1;--bg:#0d0d0d;--card:#1a1a1a;--card2:#222;--line:#2b2b2b;--lime:#d4af37;--txt:#e9e9e9;--mut:#9a9a9a}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{background:var(--bg);color:var(--txt);font-family:'Cairo',Tahoma,sans-serif;direction:rtl;text-align:right;line-height:1.8;font-size:16px}
a{color:inherit;text-decoration:none}
.wrap{max-width:1100px;margin:0 auto;padding:0 18px}
.topbar{position:sticky;top:0;z-index:50;background:rgba(13,13,13,.92);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}
.topbar .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:62px;flex-wrap:wrap}
.brand{font-weight:900;font-size:20px;color:var(--lime);letter-spacing:.3px}
.menu{display:flex;gap:6px;flex-wrap:wrap;margin:0;padding:0;list-style:none}
.menu a{display:block;padding:6px 14px;border-radius:999px;font-weight:600;font-size:15px;color:var(--txt);border:1px solid transparent}
.menu a:hover{border-color:var(--lime);color:var(--lime)}
.author{margin:34px 0 10px;background:linear-gradient(180deg,#1a160a 0%,#121212 70%);border:1px solid var(--line);border-radius:26px;padding:34px 30px;display:flex;gap:30px;align-items:center}
.author img{width:150px;height:150px;border-radius:50%;object-fit:cover;border:4px solid var(--lime);flex:none}
.author h1{margin:0 0 8px;font-size:30px;font-weight:900}
.author p{margin:0;color:#cfcfcf;font-size:17px;max-width:760px}
.chips{display:flex;gap:8px;margin-top:14px;flex-wrap:wrap}
.chip{background:#101010;border:1px solid var(--line);border-radius:999px;padding:3px 14px;font-size:13px;color:var(--mut)}
.chip b{color:var(--lime)}
h2.sec{display:flex;align-items:center;gap:16px;color:var(--lime);font-size:26px;font-weight:900;margin:44px 0 22px}
h2.sec:after{content:'';flex:1;height:1px;background:var(--line)}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(310px,1fr));gap:20px}
.card{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:22px;display:flex;flex-direction:column;gap:10px;transition:.2s}
.card:hover{border-color:var(--lime);transform:translateY(-3px)}
.tag{align-self:flex-start;background:#101010;border:1px solid var(--line);border-radius:999px;padding:1px 12px;font-size:12px;color:var(--mut)}
.card h3{margin:2px 0;font-size:21px;font-weight:700}
.card .snip{margin:0;color:var(--mut);font-size:15px;flex:1}
.btn{display:inline-block;align-self:flex-start;background:var(--lime);color:#111;font-weight:800;border-radius:12px;padding:8px 22px;font-size:15px}
.btn:hover{filter:brightness(1.08)}
.empty{background:var(--card);border:1px dashed var(--line);border-radius:20px;padding:34px;text-align:center;color:var(--mut)}
.full{background:var(--card);border:1px solid var(--line);border-radius:22px;padding:34px 30px;margin:34px 0}
.full h1{margin:0 0 6px;font-size:32px;font-weight:900;color:var(--lime)}
.full .meta{color:var(--mut);font-size:14px;margin-bottom:22px}
.post-body{font-size:calc(1.2rem * var(--z));line-height:2.1;color:#ececec}
.post-body img{max-width:100%;height:auto;border-radius:14px}
.pager{display:flex;justify-content:space-between;margin:30px 0}
.pager a{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:8px 20px}
.pager a:hover{border-color:var(--lime);color:var(--lime)}
.zoom{position:fixed;left:16px;bottom:16px;z-index:99;display:flex;gap:6px;background:#141414;border:1px solid var(--line);border-radius:999px;padding:6px 8px;box-shadow:0 6px 24px rgba(0,0,0,.5)}
.zoom button{background:var(--card2);color:var(--txt);border:1px solid var(--line);border-radius:999px;width:42px;height:42px;font:700 17px 'Cairo',sans-serif;cursor:pointer}
.zoom button:hover{background:var(--lime);color:#111}
.foot{border-top:1px solid var(--line);margin-top:50px;padding:26px 0 90px;text-align:center;color:var(--mut);font-size:14px}
.hidden-widgets,.raw{display:none}
@media(max-width:640px){.author{flex-direction:column;text-align:center;padding:26px 18px}.author h1{font-size:25px}.brand{font-size:18px}.full{padding:22px 16px}.full h1{font-size:26px}}

.blog-posts{display:grid;grid-template-columns:repeat(auto-fill,minmax(310px,1fr));gap:20px;margin:0}
.date-outer,.date-posts{display:contents}
.date-header,.post-footer,.post-share-buttons,.post-timestamp,.post-icons,.post-labels,.post-feeds,.blog-feeds,.status-msg-wrap,.post-author,.post-comment-link,.post-location,.post-reactions,.reactions-label-cell{display:none!important}
.post-outer{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:22px;display:flex;flex-direction:column;gap:10px;transition:.2s}
.post-outer:hover{border-color:var(--lime);transform:translateY(-3px)}
.post{margin:0}
.post-title,.post-title a{margin:2px 0;font-size:21px;font-weight:700;color:var(--txt)}
.pt-index .post-body{display:none}
.pt-index .snip{margin:0;color:var(--mut);font-size:15px}
.pt-item .blog-posts,.pt-static_page .blog-posts{display:block}
.pt-item .post-outer,.pt-static_page .post-outer{border-radius:22px;padding:34px 30px;margin:34px 0}
.pt-item .post-outer:hover,.pt-static_page .post-outer:hover{transform:none;border-color:var(--line)}
.pt-item .post-title,.pt-static_page .post-title{font-size:32px;font-weight:900;color:var(--lime)}
.blog-pager{display:flex;justify-content:space-between;margin:30px 0;grid-column:1/-1}
.blog-pager a{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:8px 20px}
#blog-pager{overflow:hidden}
.pt-item .post-body,.pt-static_page .post-body{display:block}
.btn,.zoom button:hover{background:linear-gradient(135deg,#f7e08a 0%,#d4af37 45%,#a67c00 100%)!important;color:#1a1200!important}
.brand,h2.sec,.pt-item .post-title,.pt-static_page .post-title,.author h1{background:linear-gradient(135deg,#fff0a8 0%,#d4af37 45%,#b8860b 100%);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent}
.author img{border-color:#d4af37;box-shadow:0 0 18px rgba(212,175,55,.35)}
@media(max-width:640px){.topbar{position:static}.menu a{padding:4px 10px;font-size:14px}}
.comments{margin-top:26px;background:#fff;color:#222;border-radius:16px;padding:16px}.pt-static_page .comments,.pt-index .comments{display:none}
.byline{margin:-4px 0 18px;font-size:15px;color:var(--mut)}.byline a{color:var(--lime);font-weight:700}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
