(function(){
var k='wm_zoom',z=parseFloat(localStorage.getItem(k))||1;
function ap(){document.documentElement.style.setProperty('--z',z);localStorage.setItem(k,z)}
ap();
document.getElementById('zp').onclick=function(){z=Math.min(1.8,+(z+0.1).toFixed(2));ap()};
document.getElementById('zm').onclick=function(){z=Math.max(0.8,+(z-0.1).toFixed(2));ap()};
var cs=document.querySelectorAll('.card');
for(var i=0;i<cs.length;i++){var r=cs[i].querySelector('.raw'),s=cs[i].querySelector('.snip');
if(r&&s){var t=(r.textContent||'').replace(/\s+/g,' ').trim();s.textContent=t.length>170?t.slice(0,170)+'...':t}}
var po=document.querySelectorAll('.pt-index .post-outer,.pt-archive .post-outer');
for(var q=0;q<po.length;q++){var b=po[q].querySelector('.post-body'),a=po[q].querySelector('.post-title a');
var tx=b?(b.textContent||'').replace(/\s+/g,' ').trim():'';var p=document.createElement('p');p.className='snip';p.textContent=tx.length>170?tx.slice(0,170)+'...':tx;po[q].appendChild(p);
if(a){var l=document.createElement('a');l.className='btn';l.href=a.href;l.textContent='اقرأ الآن';po[q].appendChild(l)}}
var pg=document.querySelectorAll('.blog-pager a,#blog-pager a');for(var w=0;w<pg.length;w++){var x=pg[w].textContent.trim();if(x=='Home'||x=='الصفحة الرئيسية')pg[w].textContent='الرئيسية';else if(x=='رسائل أقدم')pg[w].textContent='الأقدم';else if(x=='رسائل أحدث')pg[w].textContent='الأحدث';else if(x=='Newer Posts')pg[w].textContent='الأحدث';else if(x=='Older Posts')pg[w].textContent='الأقدم'}
var pt=document.querySelector('.pt-item .post-title');if(pt){var bl=document.createElement('div');bl.className='byline';bl.innerHTML='بقلم <a href="/p/blog-page.html">محمد عاشور عبدالعاطي</a>';pt.parentNode.insertBefore(bl,pt.nextSibling)}
})();
