(function(){
var D=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
function ar(n){return String(n).replace(/[0-9]/g,function(d){return '٠١٢٣٤٥٦٧٨٩'[d]})}
function fd(iso){var d=new Date(iso);if(isNaN(d))return '';return ar(d.getDate())+' '+D[d.getMonth()]+' '+ar(d.getFullYear())}
var m=document.querySelector('.topbar .menu');
if(m){var f=document.createElement('form');f.className='srch';f.action='/search';f.method='get';f.innerHTML='<input name="q" type="search" placeholder="ابحث..."/><button type="submit">بحث</button>';m.parentNode.appendChild(f)}
var it=document.querySelector('.pt-item .post-outer');
if(it){var ab=it.querySelector('abbr.published'),lb=it.querySelector('.post-labels a'),by=it.querySelector('.byline');
var mt=document.createElement('div');mt.className='meta2';
if(ab)mt.innerHTML+='<span>'+fd(ab.getAttribute('title'))+'</span>';
if(lb){var tg=document.createElement('a');tg.className='tag';tg.href=lb.href;tg.textContent=lb.textContent;mt.appendChild(tg)}
if(by)by.parentNode.insertBefore(mt,by.nextSibling);
var u=encodeURIComponent(location.href.split('?')[0]),t=encodeURIComponent(document.title);
var sh=document.createElement('div');sh.className='share';
sh.innerHTML='<span>شارك:</span><a target="_blank" rel="noopener" href="https://wa.me/?text='+t+'%20'+u+'">واتساب</a><a target="_blank" rel="noopener" href="https://www.facebook.com/sharer/sharer.php?u='+u+'">فيسبوك</a><a target="_blank" rel="noopener" href="https://twitter.com/intent/tweet?url='+u+'&text='+t+'">X</a><button type="button" id="cpl">نسخ الرابط</button>';
var bd=it.querySelector('.post-body');bd.parentNode.insertBefore(sh,bd.nextSibling);
document.getElementById('cpl').onclick=function(){var b=this;(navigator.clipboard?navigator.clipboard.writeText(location.href.split('?')[0]):Promise.reject()).then(function(){b.textContent='تم النسخ'},function(){b.textContent='انسخه من شريط العنوان'})};
var nw=document.querySelector('#blog-pager-newer-link a'),od=document.querySelector('#blog-pager-older-link a');
if(nw||od){var pn=document.createElement('div');pn.className='pn';pn.innerHTML=(od?'<a href="'+od.href+'">&rarr; القصة السابقة</a>':'')+(nw?'<a href="'+nw.href+'">القصة التالية &larr;</a>':'');sh.parentNode.insertBefore(pn,sh.nextSibling)}}
var cs=document.querySelectorAll('.pt-index .post-outer,.pt-archive .post-outer');
for(var i=0;i<cs.length;i++){var c=cs[i],im=c.querySelector('.post-body img'),a2=c.querySelector('abbr.published'),h=c.querySelector('h3');
if(im){var g=document.createElement('img');g.className='cov';g.loading='lazy';g.decoding='async';g.src=im.src;g.alt='';c.insertBefore(g,c.firstChild)}
if(a2&&h){var dd=document.createElement('div');dd.className='meta2';dd.textContent=fd(a2.getAttribute('title'));h.parentNode.insertBefore(dd,h.nextSibling)}}
var ft=document.querySelector('.foot');if(ft){ft.innerHTML='<div class="soc" id="soc"><a class="sbtn" href="https://www.facebook.com/Ashour.Walker" rel="me noopener" target="_blank">فيسبوك</a><a class="sbtn" href="https://www.tiktok.com/@moashour31" rel="me noopener" target="_blank">تيك توك</a><a class="sbtn" href="https://chat.whatsapp.com/I1VB3XGnd0JIbYiJ6ZrX8R?s=cl&amp;p=a&amp;iam=2" rel="noopener" target="_blank">انضم لجروب القرّاء على واتساب</a></div><div class="sfoot">© متحف الكتابة - محمد عاشور عبدالعاطي</div>'}
