(function(){
function ar(n){return String(n).replace(/[0-9]/g,function(d){return '٠١٢٣٤٥٦٧٨٩'[d]})}
function rtx(n){return n<=1?'دقيقة قراءة':n==2?'دقيقتان قراءة':n<=10?ar(n)+' دقائق قراءة':ar(n)+' دقيقة قراءة'}
var cs=document.querySelectorAll('.pt-index .post-outer,.pt-archive .post-outer');for(var c=0;c<cs.length;c++){var bb=cs[c].querySelector('.post-body'),m2=cs[c].querySelector('.meta2');if(bb&&m2){var ww=(bb.textContent||'').replace(/\s+/g,' ').trim().split(' ').length;var sp=document.createElement('span');sp.className='rt';sp.textContent='\u23F1 '+rtx(Math.max(1,Math.round(ww/180)));m2.appendChild(sp)}}
var tt=document.createElement('button');tt.id='totop';tt.setAttribute('aria-label','لأعلى');tt.innerHTML='&uarr;';tt.onclick=function(){window.scrollTo({top:0,behavior:'smooth'})};document.body.appendChild(tt);
var bar=null,it=document.querySelector('.pt-item .post-outer');
if(it){bar=document.createElement('div');bar.id='rp';document.body.appendChild(bar);
var bd=it.querySelector('.post-body'),w=(bd.innerText||'').replace(/\s+/g,' ').trim().split(' ').length,mn=Math.max(1,Math.round(w/180));
var mt=it.querySelector('.meta2');if(mt){var s=document.createElement('span');s.className='rt';s.textContent=rtx(mn);mt.appendChild(s)}
var sh=it.querySelector('.share');
var sb=document.createElement('div');sb.className='subs';sb.innerHTML='<b>لا تفوّت جديد المتحف</b><p>تابع القصص الجديدة أول بأول</p><a class="sbtn" href="https://chat.whatsapp.com/I1VB3XGnd0JIbYiJ6ZrX8R?s=cl&p=a&iam=2" target="_blank" rel="noopener">جروب القرّاء على واتساب</a><a class="sbtn" href="/feeds/posts/default" target="_blank">اشتراك RSS</a><a class="sbtn" href="https://www.facebook.com/Ashour.Walker" target="_blank" rel="noopener">تابعني على فيسبوك</a>';
